def test_invalid_elf_header():
    mock_data = b"InvalidHeader"
    with BytesIO(mock_data) as mock_file:
        with pytest.raises(uchecker.NotAnELFException):
            uchecker.get_build_id(mock_file)


def test_elf_without_build_id():
    # Construct a mock ELF64 binary without a build ID
    mock_elf_data = b"\x7fELF\x02\x01" + b"\x00" * 100  # Rest of the mock ELF data
    with BytesIO(mock_elf_data) as mock_file:
        with pytest.raises(uchecker.BuildIDParsingException):
            uchecker.get_build_id(mock_file)
